<?php
declare(strict_types=1);
require_once __DIR__ . '/../PRACTICAL-10/session.php';
$user=sh_auth_user();if(!$user){header('Location: ../PRACTICAL-10/login.php'.(!empty($_SESSION['session_expired'])?'?expired=1':''));exit;}
if(($user['role']??'')!=='admin'){http_response_code(403);exit('Access denied: administrator role required.');}
$csrf=sh_csrf_token();$e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
$errors=[];$stats=[];$activity=[];$auth=[];$eventAudit=[];
try{
 $db=studentHubMysqli();
 if($_SERVER['REQUEST_METHOD']==='POST'){
  if(!sh_valid_csrf($_POST['csrf_token']??null)){$errors[]='Invalid security token.';}
  elseif(($_POST['action']??'')==='record_visit'){
   $s=$db->prepare('INSERT INTO admin_activity_log(admin_user_id,action,details) VALUES(?,?,?)');$uid=(int)$user['user_id'];$action='dashboard_view';$details='Admin opened dashboard';$s->bind_param('iss',$uid,$action,$details);$s->execute();$s->close();header('Location: dashboard.php?logged=1');exit;
  }
 }
 $queries=['Students'=>'SELECT COUNT(*) FROM students','Active students'=>"SELECT COUNT(*) FROM students WHERE status='active'",'Events'=>'SELECT COUNT(*) FROM events','Open events'=>"SELECT COUNT(*) FROM events WHERE status='open'",'Registrations'=>'SELECT COUNT(*) FROM registrations','User accounts'=>'SELECT COUNT(*) FROM users','Administrators'=>"SELECT COUNT(*) FROM users WHERE role='admin'"];
 foreach($queries as $label=>$sql)$stats[$label]=(int)$db->query($sql)->fetch_row()[0];
 $activity=$db->query('SELECT l.action,l.details,l.occurred_at,u.username FROM admin_activity_log l JOIN users u ON u.user_id=l.admin_user_id ORDER BY l.audit_id DESC LIMIT 12')->fetch_all(MYSQLI_ASSOC);
 $auth=$db->query('SELECT a.event_type,a.occurred_at,COALESCE(u.username,\'Unknown\') AS username FROM auth_audit_log a LEFT JOIN users u ON u.user_id=a.user_id ORDER BY a.audit_id DESC LIMIT 12')->fetch_all(MYSQLI_ASSOC);
 $eventAudit=$db->query('SELECT a.event_type,a.event_id,a.occurred_at,u.username FROM event_management_audit a JOIN users u ON u.user_id=a.admin_user_id ORDER BY a.audit_id DESC LIMIT 12')->fetch_all(MYSQLI_ASSOC);
}catch(Throwable $ex){error_log('P14 dashboard: '.$ex->getMessage());$errors[]='Could not load dashboard. Import Practical 14 SQL and the earlier Practical 8–12 migrations.';}
?><!doctype html><html lang="en-IN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>StudentHub | Admin Dashboard</title><link rel="stylesheet" href="../PRACTICAL-03/css/style.css"><style>.p14-stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(175px,1fr));gap:15px}.p14-stat{padding:20px;border:1px solid var(--border,#ccd8ce);border-radius:12px;background:var(--surface,#fff)}.p14-stat strong{display:block;font-size:2rem;color:var(--heading,#183c35)}.p14-table-wrap{overflow-x:auto}.p14-table{width:100%;border-collapse:collapse;min-width:490px}.p14-table td,.p14-table th{padding:10px;border-bottom:1px solid var(--border,#ccd8ce);text-align:left}.p14-links{display:flex;gap:12px;flex-wrap:wrap}.p14-error{padding:12px;color:#9b3c36}</style></head><body><a class="skip-link" href="#main-content">Skip to content</a><header><h1>StudentHub</h1><p>Administrator · Practical 14 · Live Dashboard</p></header><nav aria-label="Role-based navigation"><a href="../PRACTICAL-02/index.html">Home</a><a href="../PRACTICAL-10/dashboard.php">Main Dashboard</a><?php if(($user['role']??'')==='admin'):?><a href="../PRACTICAL-11/students.php">Students</a><a href="../PRACTICAL-12/events.php">Events</a><a href="../PRACTICAL-13/index.php">AJAX CRUD</a><a href="dashboard.php" aria-current="page">Admin Analytics</a><?php endif;?></nav><main id="main-content"><section><h2>Welcome, <?= $e($user['full_name']) ?></h2><p>Admin-only dashboard with live MySQL statistics and audit history.</p><?php foreach($errors as $error):?><p class="p14-error" role="alert"><?= $e($error) ?></p><?php endforeach;?><div class="p14-stats"><?php foreach($stats as $label=>$count):?><div class="p14-stat"><strong><?= (int)$count ?></strong><?= $e($label) ?></div><?php endforeach;?></div></section><section><h2>Quick actions</h2><div class="p14-links"><a href="../PRACTICAL-11/students.php">Manage students</a><a href="../PRACTICAL-12/events.php">Manage events</a><a href="../PRACTICAL-13/index.php">Manage students with AJAX</a></div><form method="post"><input type="hidden" name="csrf_token" value="<?= $e($csrf) ?>"><button type="submit" name="action" value="record_visit">Record dashboard visit in audit log</button></form><?php if(isset($_GET['logged'])):?><p role="status">Dashboard visit recorded successfully.</p><?php endif;?></section><section><h2>Admin activity audit</h2><div class="p14-table-wrap"><table class="p14-table"><thead><tr><th>Admin</th><th>Action</th><th>Details</th><th>Time</th></tr></thead><tbody><?php foreach($activity as $row):?><tr><td><?= $e($row['username']) ?></td><td><?= $e($row['action']) ?></td><td><?= $e($row['details']) ?></td><td><?= $e($row['occurred_at']) ?></td></tr><?php endforeach;?><?php if(!$activity):?><tr><td colspan="4">No admin activity yet. Use the record button above.</td></tr><?php endif;?></tbody></table></div></section><section><h2>Authentication audit (Practical 10)</h2><div class="p14-table-wrap"><table class="p14-table"><thead><tr><th>User</th><th>Event</th><th>Time</th></tr></thead><tbody><?php foreach($auth as $row):?><tr><td><?= $e($row['username']) ?></td><td><?= $e($row['event_type']) ?></td><td><?= $e($row['occurred_at']) ?></td></tr><?php endforeach;?></tbody></table></div></section><section><h2>Event changes (Practical 12)</h2><div class="p14-table-wrap"><table class="p14-table"><thead><tr><th>Admin</th><th>Event ID</th><th>Action</th><th>Time</th></tr></thead><tbody><?php foreach($eventAudit as $row):?><tr><td><?= $e($row['username']) ?></td><td><?= $e($row['event_id']??'Deleted') ?></td><td><?= $e($row['event_type']) ?></td><td><?= $e($row['occurred_at']) ?></td></tr><?php endforeach;?></tbody></table></div></section></main><footer><p>StudentHub · Practical 14</p><form method="post" action="../PRACTICAL-10/logout.php"><input type="hidden" name="csrf_token" value="<?= $e($csrf) ?>"><button type="submit">Sign out</button></form></footer></body></html>
